CREATE TEMP TABLE temp_import_pages (page_data jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0890000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 89, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "89", "printedPageNumber": 89, "pdfPageNumber": 472, "sequenceIndex": 79, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0890000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فَلْيُسَكِّنْ أَطْرَافَهُ لَا يَتَمَيَّلْ تَمَيُّلَ الْيَهُودِ فَإِنَّ سُكُونَ الْأَطْرَافِ فِي الصَّلَاةِ مِنْ تَمَامِ الصَّلَاةِ\nأَخْرَجَهُ الْحَكِيمُ التِّرْمِذِيُّ عَنِ ابْنِ عُمَرَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Umme Roomaan (wife of Abu Bakr) (Radhiyallaho anha) narrates, \"Once I was offering my salaat, when I unknowingly started leaning sometimes to one side and sometimes to the other. Hadhrat Abu Bakr (Radhiyallaho anho) saw me doing this and reprimanded me so harshly that I was about to abandon my salaat with fear. He told me later that he had heard the Prophet (Sallallaho alaihe wasallam) saying, \"When a person stands for salaat, he should keep his body at rest and he should not behave like the Jews, since to remain motionless is one of the complements of salaat.\"\n\nKeeping the body at rest during salaat is enjoined in many ahaadith. In the beginning, it was a habit with the Prophet (Sallallaho alaihe wasallam) that he kept looking towards the heaven in expectation of Hadhrat Jibra-eel (Alayhis salaam) to bring him some revelation, so much so that his eyes would sometimes rise up unconsciously even during salaat. When the first two verses of Soorah XXIII (viz.,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "قَدْ أَفْلَحَ الْمُؤْمِنُونَ ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "(Successful indeed are the believers who are humble in their salaat)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}, {"id": "f0890500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "were revealed, he began to keep his gaze down while in salaat. It is also said about the companions that in the beginning they would sometime cast their glances here and there during their salaat but, after these verses were revealed, they gave up this practice. Explaining these verses, Hadhrat Abdullah bin Umar (Radhiyallaho anho) says, \"When the Sahabah stood for salaat they never looked this side or that side. They remained attentive in salaat with their eyes fixed at the place of sajdah; totally absorbed in Allah, their Lord. Someone inquired from Hadhrat Ali (Radhiyallaho anho), ''What is devotion?'' He replied, ''Concentration in salaat is included in devotion.''\"\n\nHadhrat Ibn Abbas (Radhiyallaho anho) says, \"Humble (mentioned in the above verses) are those who fear Allah and remain motionless in salaat.\"\n\nHadhrat Abu Bakr (Radhiyallaho anho) narrates, \"Once", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 89"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0900000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 90, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "90", "printedPageNumber": 90, "pdfPageNumber": 473, "sequenceIndex": 80, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0900100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VII", "sourceIdentifier": "VII", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0900000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "the Prophet (Sallallaho alaihe wasallam) said, ''Seek refuge in Allah from sanctimonious devotion.'' We inquired, ''What is sanctimonious devotion, O Prophet of Allah! (Sallallaho alaihe wasallam).'' He replied, ''To feign concentration, with nifaaq lurking in the heart.''\n\nHadhrat Abu Darda (Radhiyallaho anho) relates a similar hadith in which the Prophet (Sallallaho alaihe wasallam) is reported to have said, \"Hypocritical devotion is that in which a person outwardly pretends concentration, while his heart is devoid of that.\"\n\nHadhrat Qataadah (Radhiyallaho anho) says, \"For devotion in salaat, the heart should be full of Allah''s fear, and the gaze should be kept down.\"\n\nThe Prophet (Sallallaho alaihe wasallam) once saw a person fondling his beard while in salaat. He remarked, \"If his heart were blessed with devotion, then his entire body would be at rest.\"\n\nHadhrat Aa''ishah (Radhiyallaho anha) once inquired from the Prophet (Sallallaho alaihe wasallam) as to what his opinion was about the practice of looking around while in salaat. He said, \"It is a damage to salaat caused by Satan.\"\n\nOnce the Prophet (Sallallaho alaihe wasallam) said, \"People in the habit of looking up while in salaat must give up that habit, lest their gaze may become fixed and not return to them.\"\n\nIt has been said by many of the companions and their successors that devotion means tranquillity in salaat. The Prophet (Sallallaho alaihe wasallam) is reported (by many narrators) to have said, \"Offer each salaat (with) such (devotion) as if it were the last salaat of your life.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900200-0000-4000-8000-000000000001", "structuralNodeId": "b0900100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900300-0000-4000-8000-000000000001", "structuralNodeId": "b0900100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن عمران بن حصين رضي الله عنه قال سئل النبي ﷺ عن قول الله تعالى إن الصلاة تنهى عن الفحشاء والمنكر فقال من لم تنهه صلاته عن الفحشاء والمنكر فلا صلاة له كذا في الدر المنثور", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}, {"id": "f0900400-0000-4000-8000-000000000001", "structuralNodeId": "b0900100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Imraan bin Husain (Radhiyallaho anho) narrates, Someone inquired of the Prophet (Sallallaho alaihe wasallam) about the meaning of the verse in Qur''an:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 90"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0910000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 91, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "91", "printedPageNumber": 91, "pdfPageNumber": 474, "sequenceIndex": 81, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0910000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (c)—Quotations from Ahadith", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 91"}, {"id": "f0910100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الصَّلَاةَ تَنْهَىٰ عَنِ الْفَحْشَاءِ وَالْمُنْكَرِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 91"}, {"id": "f0910200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! Salaat restrains from shameful and unjust deeds.\" (XXIX: 45)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 91"}, {"id": "f0910300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "He replied, \"Salaat is no salaat if it does not preserve one from lewdness and iniquity.\"\n\nNo doubt, salaat is a very valuable service and when offered properly, results in preservation from all undesirables. If this result is not achieved, then there is something lacking in the proper performance of salaat. There are many other ahaadith conveying this meaning. Hadhrat Ibn Abbas (Radhiyallaho anho) says, \"Salaat has the power to check the inclination to sins.\"\n\nHadhrat Abul Aaliyah (Radhiyallaho anho) explaining the same verse of the Qur''an writes: \"There are three essentials of salaat: Sincerity, Fear of Allah, and His remembrance. Salaat is no salaat if these three are missing. Sincerity heralds virtuous deeds, fear of Allah expels vices, and His remembrance is the Qur''an, which in itself is a guidance towards good and guard against evil.\"\n\nHadhrat Ibn Abbas (Radhiyallaho anho) reports that the Prophet (Sallallaho alaihe wasallam) once said, \"Salaat that does not prevent from lewdness and iniquity instead of bringing close to Allah, takes away from Him.\"\n\nHadhrat Ibn Mas''ood (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"A person who does not follow up his salaat, has actually offered no salaat. To follow up the salaat is to shun lewdness and iniquity.\"\n\nHadhrat Abu Hurairah (Radhiyallaho anho) narrates, \"A person came to the Prophet (Sallallaho alaihe wasallam) and reported about a certain man, who was in the habit of offering salaat for the whole night and then committing a larceny before daybreak. The Prophet (Sallallaho alaihe wasallam) remarked, \"His salaat will very soon wean him off that sin.\" This shows that the evil habits can be got rid of by adhering to salaat with due sincerity. It is a difficult and lengthy affair to redeem each and every bad habit. On the contrary, it is easier and quicker to start offering salaat with proper care when through the blessings that follow it, bad habits are sure to disappear one by one.\" May Allah grant me strength to say my salaat properly!", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 91"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;